import Foundation

/// Soft key edges (ARCHITECTURE.md, "Soft key edges"): the tap prior and the decision against the Python
/// reference (`TapFixtures`, generated by localflow-swipe `python -m tap.export_ios fixtures` from
/// synthetic weights, contexts and taps), the prior's cache and window, the model file's validation, and
/// the bundle's `tap` section. Synthetic data only.
enum TapCoreTests {
    static var tests: [TestCase] {
        [
            ("normalizedContextsMatchTheReference", testNormalizedContextsMatchTheReference),
            ("normalizationFoldsLikePython", testNormalizationFoldsLikePython),
            ("logProbsMatchTheReference", testLogProbsMatchTheReference),
            ("surpriseMatchesTheReference", testSurpriseMatchesTheReference),
            ("incrementalCacheMatchesACold", testIncrementalCacheMatchesACold),
            ("cacheIsBoundedAndClears", testCacheIsBoundedAndClears),
            ("longContextsReadTheirLastWindow", testLongContextsReadTheirLastWindow),
            ("modelFileIsValidated", testModelFileIsValidated),
            ("touchLikelihoodsMatchTheReference", testTouchLikelihoodsMatchTheReference),
            ("decisionsMatchTheReference", testDecisionsMatchTheReference),
            ("centreBoxAndFunctionKeysAreNeverOverridden", testCentreBoxAndFunctionKeysAreNeverOverridden),
            ("resolveKeepsTheRecordedKeyWhenTheLayoutMoved", testResolveKeepsTheRecordedKeyWhenTheLayoutMoved),
            ("cacheIsBoundToOneField", testCacheIsBoundToOneField),
            ("logNdtrIsFiniteAndContinuous", testLogNdtrIsFiniteAndContinuous),
            ("manifestReadsTheTapSection", testManifestReadsTheTapSection),
            ("manifestRejectsAnInvalidTapSection", testManifestRejectsAnInvalidTapSection),
            ("ruleIsTheBundlesWithTheGateOn", testRuleIsTheBundlesWithTheGateOn),
        ]
    }

    private static func model() -> TapModel {
        try! TapModel(data: Data(base64Encoded: TapFixtures.gruBase64)!)
    }

    private static func prior() -> TapPrior { TapPrior(model: model(), surpriseWindow: 8) }

    /// The geometry the fixture was generated for.
    private static let keys = KeyboardLayout.referenceLetterKeys(metrics: KeyboardMetrics(width: TapFixtures.width, height: TapFixtures.height))

    private static func expectClose(_ actual: [Double], _ expected: [Double], tolerance: Double, _ message: String) {
        TestSupport.expect(actual.count == expected.count, "\(message): count")
        for (a, e) in zip(actual, expected) where !(abs(a - e) <= tolerance) {
            TestSupport.expect(false, "\(message): \(a) vs \(e)")
            return
        }
    }

    // MARK: Prior

    private static func testNormalizedContextsMatchTheReference() {
        for context in TapFixtures.contexts {
            TestSupport.expectEqual(TapPrior.normalizeContext(context.text), context.normalized)
        }
    }

    private static func testNormalizationFoldsLikePython() {
        let cases: [(String, String)] = [
            ("a\r\nb", "b"), ("one\u{2028}two", "two"), ("x\u{85}y", "y"), ("tab\there", "tab here"),
            ("  lead", "lead"), ("x\u{A0}", "x "), ("e\u{301}t\u{E9}", "ete"), ("`hi`", "'hi'"), ("I\u{2BC}m", "i'm"),
            ("\u{FF28}\u{FF49}", "hi"), ("\u{FB01}ne", "fine"), ("\u{663}\u{B2}", "00"), ("a\u{1C}b", "a b"),
            ("a\u{B}b\u{C}", "a b "), ("why?! ok.", "why.. ok."), ("\u{3A9}mega_", "#mega#"), ("   ", ""), ("", ""),
            ("a  \n  ", ""), ("end \u{3000}", "end "),
        ]
        for (text, expected) in cases {
            TestSupport.expect(TapPrior.normalizeContext(text) == expected, "normalize \(text.unicodeScalars.map { $0.value })")
        }
    }

    private static func testLogProbsMatchTheReference() {
        // One prior for every context (the cache in use) and a fresh one each (cold): both match.
        var shared = prior()
        for context in TapFixtures.contexts {
            var cold = prior()
            expectClose(cold.logProbs(context: context.text), context.logProbs, tolerance: 1e-4, "cold \(context.normalized)")
            expectClose(shared.logProbs(context: context.text), context.logProbs, tolerance: 1e-4, "shared \(context.normalized)")
        }
        TestSupport.expectEqual(TapFixtures.contexts.first?.logProbs.count, TapDecoder.outputCount)
    }

    private static func testSurpriseMatchesTheReference() {
        var shared = prior()
        for context in TapFixtures.contexts {
            var cold = prior()
            let surprise = cold.recentSurprise(context: context.text)
            TestSupport.expect(abs(surprise - context.surprise) <= 1e-4, "surprise \(context.normalized): \(surprise) vs \(context.surprise)")
            let both = shared.prediction(context: context.text)
            TestSupport.expect(abs(both.surprise - context.surprise) <= 1e-4, "shared surprise \(context.normalized)")
            expectClose(both.logProbs, context.logProbs, tolerance: 1e-4, "prediction \(context.normalized)")
        }
    }

    private static func testIncrementalCacheMatchesACold() {
        // Typing a line one character at a time (each tap one step from the cached prefix), then editing
        // back and across the window: every prediction is exactly the cold one.
        let line = "the quick brown fox jumps over it, again and again"
        var typed = prior()
        var contexts = (0 ... line.count).map { String(line.prefix($0)) }
        contexts += ["the quick", "the quack", "", "new\nline", "the quick brown fox jumps over it, again and again!"]
        for context in contexts {
            var cold = prior()
            let incremental = typed.prediction(context: context), fresh = cold.prediction(context: context)
            TestSupport.expect(incremental.logProbs == fresh.logProbs, "log probs \(context)")
            TestSupport.expect(incremental.surprise == fresh.surprise, "surprise \(context)")
        }
    }

    private static func testCacheIsBoundedAndClears() {
        var prior = prior()
        let expected = prior.logProbs(context: "hello")
        for index in 0 ..< 200 { _ = prior.prediction(context: "word\(index) and more \(index % 7)") }
        TestSupport.expect(prior.cachedCount <= TapPrior.cacheLimit, "cache bounded: \(prior.cachedCount)")
        TestSupport.expect(prior.cachedCount > 0, "cache used")
        prior.clear()
        TestSupport.expectEqual(prior.cachedCount, 0)
        TestSupport.expectEqual(prior.logProbs(context: "hello"), expected)
    }

    private static func testLongContextsReadTheirLastWindow() {
        // Context length 16: a context of 16 or more symbols is its last 16 from a zero state, whatever came
        // before; a shorter one is a message start (BOS first), so a 15-symbol context is not a window.
        var prior = prior()
        let window = "runs past twenty"
        TestSupport.expectEqual(window.count, model().contextLength)
        let long = prior.logProbs(context: "a much longer context that " + window)
        TestSupport.expectEqual(prior.logProbs(context: "zzz " + window), long)
        TestSupport.expectEqual(prior.logProbs(context: window), long)
        TestSupport.expect(prior.logProbs(context: String(window.dropFirst())) != long, "a shorter context starts at BOS")
        let fixture = TapFixtures.contexts.first { $0.normalized.count > 16 }!
        expectClose(prior.logProbs(context: "prefix " + fixture.text), fixture.logProbs, tolerance: 1e-4, "window")
    }

    private static func testModelFileIsValidated() {
        let valid = Data(base64Encoded: TapFixtures.gruBase64)!
        func error(_ data: Data) -> TapModel.FormatError? {
            do {
                _ = try TapModel(data: data)
                return nil
            } catch {
                return error as? TapModel.FormatError
            }
        }
        func patched(at offset: Int, _ bytes: [UInt8]) -> Data {
            var data = valid
            data.replaceSubrange(offset ..< offset + bytes.count, with: bytes)
            return data
        }
        let header = model()
        TestSupport.expectEqual([header.embed, header.hidden, header.contextLength], [4, 8, 16])
        TestSupport.expectEqual(header.temperature, 1.25)
        TestSupport.expectEqual(error(valid), nil)
        TestSupport.expectEqual(error(patched(at: 0, Array("LFTQ".utf8))), .badMagic)
        TestSupport.expectEqual(error(Data("LF".utf8)), .wrongSize)
        TestSupport.expectEqual(error(patched(at: 4, [2, 0, 0, 0])), .unsupportedVersion)
        TestSupport.expectEqual(error(patched(at: 20, [34, 0, 0, 0])), .unsupportedShape)
        TestSupport.expectEqual(error(patched(at: 24, [27, 0, 0, 0])), .unsupportedShape)
        TestSupport.expectEqual(error(patched(at: 8, [0, 0, 0, 0])), .unsupportedShape)
        TestSupport.expectEqual(error(patched(at: 8, [5, 0, 0, 0])), .wrongSize)
        TestSupport.expectEqual(error(valid.dropLast(4)), .wrongSize)
        TestSupport.expectEqual(error(valid + Data([0])), .wrongSize)
        TestSupport.expectEqual(error(valid + Data([0, 0, 0, 0])), .wrongSize)
        // The magic is checked before the size, and the size of the header before the version.
        TestSupport.expectEqual(error(Data("LFTQ".utf8)), .badMagic)
        TestSupport.expectEqual(error(valid.prefix(31)), .wrongSize)
        TestSupport.expectEqual(error(patched(at: 4, [2, 0, 0, 0]).prefix(31)), .wrongSize)
        TestSupport.expectEqual(error(patched(at: 28, [0, 0, 0, 0])), .invalidValues)
        TestSupport.expectEqual(error(patched(at: 40, [0, 0, 0xC0, 0x7F])), .invalidValues)
    }

    // MARK: Decision

    /// The fixture's columns (a–z, then space) in the layout's key order.
    private static func outputColumns() -> [Int?] {
        keys.map { TapDecoder.outputIndex(of: $0.action) }
    }

    private static func testTouchLikelihoodsMatchTheReference() {
        let decoder = TapDecoder(touch: .standard, rule: TapDecoder.Rule(centre: 0.6, margin: 3, maxSurprise: nil))
        let columns = outputColumns()
        TestSupport.expectEqual(columns.compactMap { $0 }.sorted(), Array(0 ..< 27))
        for tap in TapFixtures.taps {
            let likelihoods = decoder.logLikelihoods(x: tap.x, y: tap.y, keys: keys)
            TestSupport.expectEqual(likelihoods.count, keys.count)
            for (index, column) in columns.enumerated() {
                guard let column else {
                    TestSupport.expect(likelihoods[index] == -.infinity, "function key \(keys[index].action)")
                    continue
                }
                let expected = tap.logLikelihood[column]
                TestSupport.expect(abs(likelihoods[index] - expected) <= 1e-6,
                                   "tap (\(tap.x), \(tap.y)) key \(keys[index].action): \(likelihoods[index]) vs \(expected)")
            }
        }
    }

    private static func label(_ action: KeyAction?) -> String {
        switch action {
        case .character(let character): return character
        case .space: return " "
        case .shift: return "shift"
        case .delete: return "delete"
        case .layer: return "layer"
        case .returnKey: return "return"
        case .nextKeyboard: return "globe"
        case nil: return "none"
        }
    }

    private static func testDecisionsMatchTheReference() {
        TestSupport.expectEqual(TapFixtures.decisions.count, 48)
        for set in TapFixtures.decisions {
            let context = TapFixtures.contexts.first { $0.text == set.context }!
            let decoder = TapDecoder(touch: .standard,
                                     rule: TapDecoder.Rule(centre: set.centre, margin: set.margin, maxSurprise: set.maxSurprise))
            let typed = TapFixtures.taps.map { tap in
                label(decoder.decide(x: tap.x, y: tap.y, keys: keys, logPrior: context.logProbs, surprise: context.surprise))
            }
            // End to end: the same decisions from this prior's own Float32 predictions.
            var prior = prior()
            let prediction = prior.prediction(context: set.context)
            let endToEnd = TapFixtures.taps.map { tap in
                label(decoder.decide(x: tap.x, y: tap.y, keys: keys, logPrior: prediction.logProbs, surprise: prediction.surprise))
            }
            TestSupport.expect(endToEnd == set.expected, "end to end \(context.normalized) centre \(set.centre) margin \(set.margin)")
            TestSupport.expect(typed == set.expected,
                                    "\(context.normalized) centre \(set.centre) margin \(set.margin) gate \(String(describing: set.maxSurprise))")
        }
    }

    private static func testCentreBoxAndFunctionKeysAreNeverOverridden() {
        // A prior that wants only "q": inside a key's centre box, and on any function key, the nearest key
        // types; at a letter's edge next to q, q wins.
        var logPrior = [Double](repeating: -40, count: 27)
        logPrior[16] = 0
        let decoder = TapDecoder(touch: .standard, rule: TapDecoder.Rule(centre: 0.6, margin: 3, maxSurprise: nil))
        for key in keys {
            let action = decoder.decide(x: key.frame.midX, y: key.frame.midY, keys: keys, logPrior: logPrior, surprise: 0)
            TestSupport.expectEqual(action, key.action)
        }
        let w = keys.first { $0.action == .character("w") }!.frame
        TestSupport.expectEqual(decoder.decide(x: w.x + 1, y: w.midY, keys: keys, logPrior: logPrior, surprise: 0), .character("q"))
        // The gate: a surprise over the limit keeps the nearest key.
        let gated = TapDecoder(touch: .standard, rule: TapDecoder.Rule(centre: 0.6, margin: 3, maxSurprise: 3))
        TestSupport.expectEqual(gated.decide(x: w.x + 1, y: w.midY, keys: keys, logPrior: logPrior, surprise: 3), .character("q"))
        TestSupport.expectEqual(gated.decide(x: w.x + 1, y: w.midY, keys: keys, logPrior: logPrior, surprise: 3.5), .character("w"))
        // A prior of the wrong size types the nearest key; no keys, nothing.
        TestSupport.expectEqual(decoder.decide(x: w.x + 1, y: w.midY, keys: keys, logPrior: [0], surprise: 0), .character("w"))
        TestSupport.expectEqual(decoder.decide(x: 1, y: 1, keys: [], logPrior: logPrior, surprise: 0), nil)
    }

    private static func testResolveKeepsTheRecordedKeyWhenTheLayoutMoved() {
        // A prior that wants only "q", so any re-decided tap would type q.
        var logPrior = [Double](repeating: -40, count: 27)
        logPrior[16] = 0
        let decoder = TapDecoder(touch: .standard, rule: TapDecoder.Rule(centre: 0.6, margin: 3, maxSurprise: nil))
        // Same layout: resolve is decide.
        let w = keys.first { $0.action == .character("w") }!.frame
        TestSupport.expectEqual(decoder.resolve(.character("w"), x: w.x + 1, y: w.midY, keys: keys, logPrior: logPrior, surprise: 0),
                                .character("q"))
        // Touched down on m's centre at 390 x 216; the keys shrank to 390 x 162 before the release, and the
        // point is now nearest another key (Return): the recorded letter types, never that key.
        let m = keys.first { $0.action == .character("m") }!.frame
        let shrunk = KeyboardLayout.keys(for: .letters, metrics: KeyboardMetrics(width: 390, height: 162), showsGlobe: false)
        let now = shrunk[KeyboardLayout.nearestKey(toX: m.midX, y: m.midY, in: shrunk)!].action
        TestSupport.expect(now != .character("m"), "the point moved off m: \(now)")
        TestSupport.expectEqual(decoder.resolve(.character("m"), x: m.midX, y: m.midY, keys: shrunk, logPrior: logPrior, surprise: 0),
                                .character("m"))
        // No keys: the recorded key.
        TestSupport.expectEqual(decoder.resolve(.character("m"), x: 1, y: 1, keys: [], logPrior: logPrior, surprise: 0), .character("m"))
    }

    private static func testCacheIsBoundToOneField() {
        var prior = prior()
        let a = UUID(), b = UUID()
        prior.bind(to: a)
        _ = prior.prediction(context: "hello there")
        TestSupport.expect(prior.cachedCount > 0, "cache used")
        prior.bind(to: a)
        TestSupport.expect(prior.cachedCount > 0, "same field keeps the cache")
        prior.bind(to: b)
        TestSupport.expectEqual(prior.cachedCount, 0)
        _ = prior.prediction(context: "other text")
        prior.bind(to: nil)
        TestSupport.expectEqual(prior.cachedCount, 0)
    }

    private static func testLogNdtrIsFiniteAndContinuous() {
        // Around each branch boundary the pieces agree, and far tails stay finite (no −∞ before a logaddexp).
        for boundary in [-1.0, -36.0] {
            let below = TapDecoder.logNdtr(boundary.nextDown), above = TapDecoder.logNdtr(boundary.nextUp)
            TestSupport.expect(abs(below - above) <= 1e-9 * max(1, abs(above)), "continuous at \(boundary): \(below) vs \(above)")
        }
        TestSupport.expect(abs(TapDecoder.logNdtr(0) - log(0.5)) <= 1e-15, "log Φ(0)")
        TestSupport.expect(TapDecoder.logNdtr(-200).isFinite, "far tail finite")
        // −800 − log 40 − log √(2π) + log(1 − 1/1600 + 3/1600² − …).
        TestSupport.expect(abs(TapDecoder.logNdtr(-40) - -804.608442013773) <= 1e-6, "log Φ(-40)")
        TestSupport.expectEqual(TapDecoder.logNdtr(40), 0)
    }

    // MARK: Bundle and settings

    private static func manifest(_ tap: String?) -> Data {
        let section = tap.map { ", \"tap\": \($0)" } ?? ""
        return Data("""
        {"format": 1, "decode": {"beam": 4, "top_k": 3, "length_power": 0.5, "freq_weight": 0.01, "length_bonus": 0.25},
         "files": {"lexicon.bin": "00"}\(section)}
        """.utf8)
    }

    private static func tapSection(models: String = #"{"232k": "tap/c.bin", "18k": "tap/a.bin", "67k": "tap/b.bin"}"#,
                                   defaultModel: String = "67k", format: Int = 1, centre: Double = 0.6, tailWeight: Double = 0.05,
                                   window: Int = 8) -> String {
        """
        {"format": \(format), "models": \(models), "default_model": "\(defaultModel)",
         "touch": {"sigma": 0.25, "ratio": 1.0, "offset_y": 0.1, "tail_weight": \(tailWeight), "tail_scale": 2.0, "space_spread": 0.6},
         "rule": {"centre": \(centre), "margin": 3.0, "max_surprise": 3.0, "surprise_window": \(window)}}
        """
    }

    private static func testManifestReadsTheTapSection() {
        let decoded = try! SoftKeyEdgesManifest.decode(from: manifest(tapSection()))!
        TestSupport.expectEqual(decoded.models, ["18k": "tap/a.bin", "67k": "tap/b.bin", "232k": "tap/c.bin"])
        TestSupport.expectEqual(decoded.defaultModel, "67k")
        TestSupport.expectEqual(decoded.touch, SoftKeyEdgesManifest.Touch(sigma: 0.25, ratio: 1, offsetY: 0.1, tailWeight: 0.05,
                                                                         tailScale: 2, spaceSpread: 0.6))
        TestSupport.expectEqual(TapDecoder.TouchModel(decoded.touch), .standard)
        TestSupport.expectEqual(decoded.rule, SoftKeyEdgesManifest.Rule(centre: 0.6, margin: 3, maxSurprise: 3, surpriseWindow: 8))
        // No section: no soft key edges, and the swipe settings read as before.
        TestSupport.expectEqual(try! SoftKeyEdgesManifest.decode(from: manifest(nil)), nil)
        TestSupport.expectEqual(try? SwipeBundleManifest.decodeConfig(from: manifest(tapSection())),
                                SwipeDecodeConfig(beam: 4, topK: 3, lengthPower: 0.5, freqWeight: 0.01, lengthBonus: 0.25))
    }

    private static func testManifestRejectsAnInvalidTapSection() {
        func error(_ tap: String) -> SoftKeyEdgesManifest.ManifestError? {
            do {
                _ = try SoftKeyEdgesManifest.decode(from: manifest(tap))
                return nil
            } catch {
                return error as? SoftKeyEdgesManifest.ManifestError
            }
        }
        TestSupport.expectEqual(error(tapSection(format: 2)), .unsupportedFormat)
        TestSupport.expectEqual(error(tapSection(defaultModel: "1M")), .invalidModels)
        TestSupport.expectEqual(error(tapSection(models: "{}")), .invalidModels)
        for path in ["/tap/a.bin", "../a.bin", "tap/../a.bin", "tap//a.bin", "./a.bin", ""] {
            TestSupport.expect(error(tapSection(models: "{\"67k\": \"\(path)\"}")) == .invalidModels, path)
        }
        // The rule's values within their ranges: centre 0.3–0.9, margin 1–10, maximum surprise 2–8 bits.
        TestSupport.expectEqual(SoftKeyEdgesManifest.Rule.centreRange, 0.3 ... 0.9)
        TestSupport.expectEqual(SoftKeyEdgesManifest.Rule.marginRange, 1 ... 10)
        TestSupport.expectEqual(SoftKeyEdgesManifest.Rule.maxSurpriseRange, 2 ... 8)
        TestSupport.expectEqual(error(tapSection(centre: 0.95)), .invalidSettings)
        TestSupport.expectEqual(error(tapSection(centre: 0.25)), .invalidSettings)
        TestSupport.expectEqual(error(tapSection(centre: 0.3)), nil)
        TestSupport.expectEqual(error(tapSection(centre: 0.9)), nil)
        TestSupport.expectEqual(error(tapSection(tailWeight: 1)), .invalidSettings)
        TestSupport.expectEqual(error(tapSection(window: 0)), .invalidSettings)
        // A section of the wrong shape throws too (the keyboard then has no soft key edges).
        TestSupport.expect((try? SoftKeyEdgesManifest.decode(from: manifest(#"{"format": 1}"#))) == nil, "incomplete section")
    }

    /// The keyboard decides with the bundle's rule as it is, the surprise gate on.
    private static func testRuleIsTheBundlesWithTheGateOn() {
        let bundled = SoftKeyEdgesManifest.Rule(centre: 0.45, margin: 5, maxSurprise: 6, surpriseWindow: 8)
        TestSupport.expectEqual(TapDecoder.Rule(bundled), TapDecoder.Rule(centre: 0.45, margin: 5, maxSurprise: 6))
        let decoded = try! SoftKeyEdgesManifest.decode(from: manifest(tapSection()))!
        TestSupport.expectEqual(TapDecoder.Rule(decoded.rule), TapDecoder.Rule(centre: 0.6, margin: 3, maxSurprise: 3))
    }
}
